function leagueCards(){shell(`<main><p class="eyebrow">PRIVATE · 2026</p><h1>League Select</h1><a class="data-center-entry" href="#/player-data-center"><small>GLOBAL · MANUAL · LOCAL FIRST</small><h2>PLAYER DATA CENTER</h2><p>Update activated rankings, ADP, projections, injuries and loaded news before entering a league.</p></a><div class="cards">${['believeland','robocop'].map(s=>{const x=seedSetup(s as 'believeland'|'robocop');return`<a href="#/${s}"><small>${x.settings.scoringLabel}</small><h2>${x.league.name}</h2><p>12 teams · ${x.draft.keeperCount?`${x.draft.keeperCount} keepers`:'Redraft'}</p></a>`}).join('')}</div></main>`)}
