function order(){
  const hasRecordedPicks=!!ctx?.events.some(event=>event.type==='PICK_MADE');
  let editing=false,draftOrder=[...setup.draftSlots].sort((a,b)=>a.slot-b.slot).map(item=>item.originalTeamId);
  const render=()=>{
    const previewSetup={...setup,draftSlots:draftOrder.map((originalTeamId,index)=>({seasonId:setup.season.id,slot:index+1,originalTeamId}))},preview=createDraftPlan(previewSetup).filter(pick=>pick.round<=3);
    shell(`<main><a href="#/${setup.league.slug}">← Dashboard</a><p class="eyebrow">LEAGUE ADMINISTRATION</p><h1>${setup.league.name} Draft Order</h1><p>The saved order is the base Round 1 order. ${setup.draft.snake?'Even rounds reverse team ownership; chronological pick numbers always count upward.':'Every round follows the base order.'}</p>${hasRecordedPicks?'<p class="order-warning">Draft order cannot be changed after picks have been recorded. Start a new draft session first.</p>':''}${setup.ownership.length?'<p class="order-warning">Draft order cannot be changed while pick ownership overrides exist. Review or remove those trades first.</p>':''}<div class="toolbar"><button id="edit-order" ${hasRecordedPicks||setup.ownership.length||editing?'disabled':''}>EDIT DRAFT ORDER</button></div><h2>Base order</h2><div class="order order-editor">${draftOrder.map((teamId,index)=>`<div><b>${index+1}</b><span>${name(teamId)}</span>${editing?`<button data-move="up" data-index="${index}" ${index===0?'disabled':''}>MOVE UP</button><button data-move="down" data-index="${index}" ${index===draftOrder.length-1?'disabled':''}>MOVE DOWN</button>`:''}</div>`).join('')}</div>${editing?'<div class="toolbar"><button id="save-order">SAVE ORDER</button><button id="cancel-order">CANCEL</button></div>':''}<h2>Snake preview</h2><div class="order-preview">${[1,2,3].map(round=>`<section><h3>Round ${round}</h3>${preview.filter(pick=>pick.round===round).map(pick=>`<div><b>${pick.round}.${pick.pickInRound}</b><span>${name(pick.currentTeamId)}</span><small>Overall ${pick.overallPick}</small></div>`).join('')}</section>`).join('')}</div></main>`);
    document.querySelector('#edit-order')?.addEventListener('click',()=>{editing=true;render()});
    document.querySelectorAll<HTMLElement>('[data-move]').forEach(button=>button.addEventListener('click',()=>{const index=Number(button.dataset.index),target=button.dataset.move==='up'?index-1:index+1;[draftOrder[index],draftOrder[target]]=[draftOrder[target],draftOrder[index]];render()}));
    document.querySelector('#cancel-order')?.addEventListener('click',()=>{editing=false;draftOrder=[...setup.draftSlots].sort((a,b)=>a.slot-b.slot).map(item=>item.originalTeamId);render()});
    document.querySelector('#save-order')?.addEventListener('click',async()=>{try{setup=setDraftOrder(setup,draftOrder);await store.saveSetup(setup);editing=false;render()}catch(error){alert((error as Error).message)}});
  };render()
}
