 if(kind==='ownership'){let round=1;const render=()=>{const plan=createDraftPlan(setup).filter(p=>p.round===round);shell(`<main><a href="#/${setup.league.slug}">← Dashboard</a><h1>Round Ownership / Pick Swaps</h1>${picksExist?'<p class="order-warning">Locked because recorded picks exist. Start a new draft first.</p>':''}<label>Round<select id="ownership-round">${Array.from({length:setup.draft.rounds},(_,i)=>i+1).map(r=>`<option ${r===round?'selected':''}>${r}</option>`).join('')}</select></label><div class="ownership-list">${plan.map(p=>`<label><b>${p.round}.${p.pickInRound}</b><small>Overall ${p.overallPick}</small><select data-owner="${p.pickInRound}" ${picksExist?'disabled':''}>${setup.teams.map(t=>`<option value="${t.id}" ${t.id===p.currentTeamId?'selected':''}>${safe(name(t.id))}</option>`).join('')}</select>${p.currentTeamId!==p.originalTeamId?'<span class="custom-owner">CUSTOM OWNER</span>':''}</label>`).join('')}</div><button id="reset-round" ${picksExist?'disabled':''}>RESET ROUND TO SNAKE</button><button id="reset-all" ${picksExist?'disabled':''}>RESET ALL PICK OWNERSHIP</button></main>`);document.querySelector<HTMLSelectElement>('#ownership-round')!.onchange=e=>{round=Number((e.target as HTMLSelectElement).value);render()};document.querySelectorAll<HTMLSelectElement>('[data-owner]').forEach(el=>el.onchange=async()=>{setup=setPickOwner(setup,round,Number(el.dataset.owner),el.value,picksExist);await store.saveSetup(setup);render()});document.querySelector('#reset-round')?.addEventListener('click',async()=>{if(confirm(`Reset Round ${round} to snake ownership?`)){setup=resetRoundOwnership(setup,round,picksExist);await store.saveSetup(setup);render()}});document.querySelector('#reset-all')?.addEventListener('click',async()=>{if(confirm('Reset every ownership override without changing base order?')){setup=resetAllOwnership(setup,picksExist);await store.saveSetup(setup);render()}})};render();return}
 shell(`<main><a href="#/${setup.league.slug}">← Dashboard</a><h1>Edit League Settings</h1><p>Scoring: ${safe(setup.settings.scoringLabel)}</p><p>Teams: ${setup.draft.teamCount} · Rounds: ${setup.draft.rounds}</p><a href="#/${setup.league.slug}">CANCEL</a></main>`)
