function keepers(){if(!setup.draft.keeperCount){location.hash=`#/${setup.league.slug}`;return}const pool=selectPlayerPool(playerPool(),playerData),locked=setup.keeperLock.status==='locked',deadline=setup.keeperLock.deadline?new Date(setup.keeperLock.deadline).toLocaleString():'No configured deadline';shell(`<main class="keeper-workspace"><a href="#/${setup.league.slug}">← Dashboard</a><h1>${setup.league.name} Keepers</h1><div class="keeper-head"><span><b>${locked?'Locked':'Editable'} · ${deadline}</b><small>${setup.keepers.length} / ${setup.draft.keeperCount*setup.draft.teamCount}</small></span><button id="lock">${locked?'UNLOCK':'LOCK'} KEEPERS</button></div><label>Search canonical players<input id="keeper-search" placeholder="Player, position, NFL team"></label><div class="keepers">${setup.teams.map(t=>`<section><h3>${safe(name(t.id))}</h3>${Array.from({length:setup.draft.keeperCount},(_,i)=>i+1).map(slot=>{const keeper=setup.keepers.find(k=>k.teamId===t.id&&k.keeperSlot===slot);return`<label>Keeper ${slot} · Round ${slot}<select data-team="${t.id}" data-slot="${slot}" ${locked?'disabled':''}><option value="">— Select player —</option>${pool.map(p=>`<option value="${p.id}" ${keeper?.player.id===p.id?'selected':''}>${safe(p.displayName)} · ${p.position} · ${p.nflTeam??'FA'} · ECR ${p.currentBaselineRank??p.baselineRank??'—'}</option>`).join('')}</select></label>`}).join('')}</section>`).join('')}</div><p id="keeper-feedback" role="status"></p></main>`);document.querySelector('#lock')?.addEventListener('click',async()=>{setup=lockKeepers(setup,!locked);await store.saveSetup(setup);keepers()});document.querySelector<HTMLInputElement>('#keeper-search')!.oninput=e=>{const q=(e.target as HTMLInputElement).value.toLowerCase();document.querySelectorAll<HTMLOptionElement>('.keepers option').forEach(o=>o.hidden=!!o.value&&!o.textContent!.toLowerCase().includes(q))};document.querySelectorAll<HTMLSelectElement>('[data-slot]').forEach(el=>el.onchange=async()=>{try{setup=setKeeper(setup,el.dataset.team!,Number(el.dataset.slot),pool.find(p=>p.id===el.value)??null);await store.saveSetup(setup);if(ctx){ctx={...ctx,setup};await store.saveDraft(ctx)}keepers()}catch(error){document.querySelector('#keeper-feedback')!.textContent=(error as Error).message}})}
